 import * as THREE from 'three/webgpu';
import { uv, vec3, color, mix, smoothstep, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  root.position.set(...(config.position ?? [0,0,0]));
  root.rotation.set(...(config.rotation ?? [0,0,0]));
  root.scale.set(...(config.scale ?? [1,1,1]));

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10'
  };

  const width = 7;
  const height = 6;
  const stage = new THREE.Mesh(
    new THREE.PlaneGeometry(width, height, 2, 2),
    new THREE.MeshBasicNodeMaterial({
      colorNode: mix(
        mix(color(colors.surface), color(colors.ink), smoothstep(uv().y, 0.0, 0.65)),
        color(colors.accent),
        smoothstep(uv().y, 0.85, 1.0).mul(0.08)
      ),
      side: THREE.DoubleSide
    })
  );
  stage.position.z = -2.6;
  root.add(stage);

  const cardGroup = new THREE.Group();
  root.add(cardGroup);

  const frameMat = new THREE.MeshStandardNodeMaterial({
    color: color(colors.ink),
    roughness: 0.62,
    metalness: 0.45,
    clearcoat: 0.2,
    clearcoatRoughness: 0.35
  });

  const cardW = 2.4;
  const cardH = 1.6;
  const cardD = 0.22;

  const baseGeo = new THREE.BoxGeometry(cardW, cardD, cardH);
  baseGeo.translate(0, -cardD * 0.5, 0);
  const base = new THREE.Mesh(baseGeo, frameMat);
  base.castShadow = true;
  base.receiveShadow = true;
  cardGroup.add(base);

  const rimGeo = new THREE.BoxGeometry(cardW + 0.04, cardD * 0.35, cardH + 0.04);
  rimGeo.translate(0, -cardD * 0.5 + cardD * 0.18, 0);
  const rimMat = new THREE.MeshStandardNodeMaterial({
    color: color(colors.surface),
    roughness: 0.5,
    metalness: 0.5,
    clearcoat: 0.15
  });
  const rim = new THREE.Mesh(rimGeo, rimMat);
  cardGroup.add(rim);

  const accentGeo = new THREE.BoxGeometry(cardW + 0.02, cardD * 0.08, cardH + 0.02);
  accentGeo.translate(0, -cardD * 0.5 + cardD * 0.04, 0);
  const accentMat = new THREE.MeshStandardNodeMaterial({
    color: color(colors.accent),
    emissive: color(colors.accent),
    emissiveIntensity: 0.6,
    roughness: 0.4,
    metalness: 0.3
  });
  const accentEdge = new THREE.Mesh(accentGeo, accentMat);
  cardGroup.add(accentEdge);

  const screenGeo = new THREE.PlaneGeometry(cardW - 0.16, cardH - 0.16, 64, 64);
  const screenMat = new THREE.MeshStandardNodeMaterial({
    color: color(0x888888),
    roughness: 0.45,
    metalness: 0.25
  });

  const contentMesh = new THREE.Mesh(screenGeo, screenMat);
  contentMesh.rotation.x = -Math.PI / 2;
  contentMesh.position.y = -cardD * 0.48;
  contentMesh.position.z = 0;
  contentMesh.receiveShadow = true;
  cardGroup.add(contentMesh);

  const valueText = ctx.fontAtlas.createText('32', {
    fontSize: 0.42,
    color: colors.paper,
    align: 'left'
  });
  valueText.position.set(-cardW * 0.42, -cardD * 0.42, -cardH * 0.22);
  valueText.rotation.x = -Math.PI / 2;
  cardGroup.add(valueText);

  const labelText = ctx.fontAtlas.createText('MOVEMENTS', {
    fontSize: 0.13,
    color: colors.accent,
    align: 'left',
    letterSpacingPx: 2
  });
  labelText.position.set(-cardW * 0.42, -cardD * 0.38, 0.18);
  labelText.rotation.x = -Math.PI / 2;
  cardGroup.add(labelText);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (tex) {
        tex.colorSpace = THREE.SRGBColorSpace;
        screenMat.colorNode = tex.sample(uv());
        screenMat.needsUpdate = true;
      }
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
      if (depthTex && contentMesh) {
        const d = depthTex.sample(uv()).r;
        const displaced = positionLocal.add(
          contentMesh.geometry.parameters?.width
            ? new THREE.Vector3(0, 0, 1).multiplyScalar(d * 0.08)
            : vec3(0, 0, d.mul(0.08))
        );
      }
    });
  }

  const shadowGeo = new THREE.PlaneGeometry(cardW * 1.25, cardH * 1.25, 1, 1);
  const shadowMat = new THREE.MeshBasicNodeMaterial({
    color: color('#000000'),
    transparent: true,
    opacityNode: uv().y.oneMinus().mul(0.5),
    side: THREE.DoubleSide
  });
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = -0.02;
  shadow.position.z = 0;
  root.add(shadow);

  const timeline = gsap.timeline({ paused: true });
  timeline.to(cardGroup.position, { y: 0.15, duration: 0.35, ease: 'power2.out' }, 'in');
  timeline.to(cardGroup.rotation, { x: -0.04, duration: 0.35, ease: 'power2.out' }, 'in');

  let focused = false;
  root.userData.handlers = {
    ...root.userData.handlers,
    hover: () => {
      focused = true;
      timeline.invalidate().restart();
      accentMat.emissiveIntensity = 1.1;
    },
    leave: () => {
      focused = false;
      gsap.to(cardGroup.position, { y: 0, duration: 0.35, ease: 'power2.out' });
      gsap.to(cardGroup.rotation, { x: 0, duration: 0.35, ease: 'power2.out' });
      accentMat.emissiveIntensity = 0.6;
    },
    click: () => {
      gsap.timeline()
        .to(cardGroup.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
        .to(cardGroup.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'power2.out' });
      ctx.emit('hub-features.select', { nodeId: config.id });
    }
  };

  const primitiveResults = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    if (typeof ctx.primitives[p.name] === 'function') {
      const res = ctx.primitives[p.name](cardGroup, p.params ?? {});
      if (res) primitiveResults.push(res);
    }
  }

  root.userData.cleanup = () => {
    timeline.kill();
    primitiveResults.forEach(r => {
      if (r && typeof r.cleanup === 'function') r.cleanup();
    });
    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) obj.material.forEach(m => m.dispose());
        else obj.material.dispose();
      }
    });
  };

  return root;
}
